# Generated by build.py from recipe.yml for recipe tftp-choose-a-block-size. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'mkdir -p site logs'
cmd /c 'head -c 3000 /dev/urandom > site/big.bin'
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'logs/surl.log', '--directory', 'site', 'tftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -v --tftp-blksize 1024 -o copy.bin tftp://127.0.0.1:8080/big.bin 2>&1 | grep -E "blksize|tsize" } finally { Stop-Process $server0 }
